def relax(u, v, w, dist, pred):
    if dist[u] + w < dist[v]:  # 더 짧은 경로 발견
        dist[v] = dist[u] + w
        pred[v] = u  # 경로 복원용 선행 정점
        return True
    return False

def bellman_ford(vertices, edges, s):
    dist = {v: INF for v in vertices}
    pred = {v: None for v in vertices}
    dist[s] = 0
    for _ in range(len(vertices) - 1):  # V-1회
        for u, v, w in edges:
            relax(u, v, w, dist, pred)
    for u, v, w in edges:  # 더 줄어들면 음수 사이클
        if dist[u] + w < dist[v]:
            raise ValueError('음수 사이클 존재')
    return dist, pred
